class _ConstructionPropertiesDtype:
    @classmethod
    def construct_from_string(cls, string: str) -> Self:
        r"""
        Construct this type from a string.
        """
        if not isinstance(string, str):
            raise TypeError(
                f"'construct_from_string' expects a string, got {type(string)}"
            )
        # error: Non-overlapping equality check (left operand type: "str", right
        #  operand type: "Callable[[ExtensionDtype], str]")  [comparison-overlap]
        assert isinstance(cls.name, str), (cls, type(cls.name))
        if string != cls.name:
            raise TypeError(f"Cannot construct a '{cls.__name__}' from '{string}'")
        return cls()

    @classmethod
    def is_dtype(cls, dtype: object) -> bool:
        """
        Check if we match 'dtype'.
        """
        dtype = getattr(dtype, "dtype", dtype)

        if isinstance(dtype, (ABCSeries, ABCIndex, ABCDataFrame, np.dtype)):
            return False
        elif dtype is None:
            return False
        elif isinstance(dtype, cls):
            return True
        if isinstance(dtype, str):
            try:
                return cls.construct_from_string(dtype) is not None
            except TypeError:
                return False
        return False

class _EmptyMethodDtype:
    def empty(self, shape: Shape) -> ExtensionArray:
        """
        Construct an ExtensionArray of this dtype with the given shape.
        """
        cls = self.construct_array_type()
        return cls._empty(shape, dtype=self)

class _IndexClassPropertyDtype:
    @cache_readonly
    def index_class(self) -> type_t[Index]:
        """
        The Index subclass to return from Index.__new__ when this dtype is
        encountered.
        """
        from pandas import Index
        return Index

@property
def type(self) -> type_t[Any]:
    \"\"\"
    The scalar type for the array, e.g. ``int``

    It's expected ``ExtensionArray[item]`` returns an instance
    of ``ExtensionDtype.type`` for scalar ``item``, assuming
    that value is valid (not NA). NA values do not need to be
    instances of `type`.
    \"\"\"
    raise AbstractMethodError(self)

@property
def name(self) -> str:
    \"\"\"\n        A string identifying the data type.\n\n        Will be used for display in, e.g. ``Series.dtype``
    \"\"\"\
    raise AbstractMethodError(self)

@classmethod
def construct_array_type(cls) -> type_t[ExtensionArray]:
    \"\"\"\n        Return the array type associated with this dtype.\n\n        Returns\n        -------\n        type\n        \"\"\"\
    raise AbstractMethodError(cls)
